/*
 * Cupertino visual language overlay (frosted glass, hairlines, SF-like type).
 * Selectors hang off :root so demo/docs `replaceAll(':root', '[data-theme="apple"]')`
 * scopes the chrome the same way as color variables.
 */

:root {
  font-family: var(--cu-font-family-sans);
  letter-spacing: -0.022em;
  -webkit-font-smoothing: antialiased;
  background-color: var(--cu-color-background-default);
  background-image:
    radial-gradient(
      120% 70% at 8% -12%,
      color-mix(in srgb, var(--cu-color-palette-brand) 26%, transparent),
      transparent 54%
    ),
    radial-gradient(80% 50% at 100% 0%, color-mix(in srgb, #af52de 16%, transparent), transparent 48%);
}

:root .cu-app-shell {
  background:
    radial-gradient(
      120% 70% at 8% -12%,
      color-mix(in srgb, var(--cu-color-palette-brand) 22%, transparent),
      transparent 54%
    ),
    var(--cu-color-background-default);
}

:root .cu-app-shell__header,
:root .cu-navbar,
:root .cu-tab-bar,
:root .cu-navigation,
:root .cu-sidebar,
:root .cu-three-end-chrome {
  background: var(--cu-color-background-translucent);
  -webkit-backdrop-filter: saturate(var(--cu-saturate-frost)) blur(var(--cu-blur-frost));
  backdrop-filter: saturate(var(--cu-saturate-frost)) blur(var(--cu-blur-frost));
}

:root .cu-app-shell__header {
  position: sticky;
  inset-block-start: 0;
  z-index: 8;
  border-block-end: var(--cu-border-width-hairline) solid var(--cu-color-border-default);
}

:root .cu-navbar {
  border-block-end: var(--cu-border-width-hairline) solid var(--cu-color-border-default);
}

:root .cu-tab-bar {
  border-block-start: var(--cu-border-width-hairline) solid var(--cu-color-border-default);
}

:root .cu-tab-bar__item[data-state='active'] {
  border-block-start-color: transparent;
  font-weight: var(--cu-font-weight-semibold);
}

:root .cu-sidebar {
  border-inline-end: var(--cu-border-width-hairline) solid var(--cu-color-border-default);
}

:root .cu-app-shell__sidebar {
  border-inline-end: var(--cu-border-width-hairline) solid var(--cu-color-border-default);
  background: var(--cu-color-background-translucent);
  -webkit-backdrop-filter: saturate(var(--cu-saturate-frost)) blur(var(--cu-blur-frost));
  backdrop-filter: saturate(var(--cu-saturate-frost)) blur(var(--cu-blur-frost));
}

:root .cu-dialog__content,
:root .cu-action-sheet__content,
:root .cu-command-palette__content,
:root .cu-sheet,
:root .cu-drawer {
  background: var(--cu-color-background-translucent-thick);
  -webkit-backdrop-filter: saturate(var(--cu-saturate-frost)) blur(var(--cu-blur-thick));
  backdrop-filter: saturate(var(--cu-saturate-frost)) blur(var(--cu-blur-thick));
  box-shadow: var(--cu-shadow-overlay);
  border-radius: var(--cu-radius-xl);
}

:root .cu-dialog__content,
:root .cu-action-sheet__content,
:root .cu-command-palette__content {
  border-start-start-radius: var(--cu-radius-xl);
  border-start-end-radius: var(--cu-radius-xl);
}

:root .cu-popover__content,
:root .cu-menu,
:root .cu-hover-card,
:root .cu-toast {
  background: var(--cu-color-background-translucent-thick);
  -webkit-backdrop-filter: saturate(var(--cu-saturate-frost)) blur(var(--cu-blur-frost));
  backdrop-filter: saturate(var(--cu-saturate-frost)) blur(var(--cu-blur-frost));
  box-shadow: var(--cu-shadow-soft);
  border-radius: var(--cu-radius-lg);
  border-width: var(--cu-border-width-hairline);
}

:root .cu-card {
  background: var(--cu-color-background-elevated);
  border-radius: var(--cu-radius-lg);
  box-shadow: var(--cu-shadow-none);
}

:root .cu-card--elevated {
  box-shadow: var(--cu-shadow-soft);
}

:root .cu-card--outlined {
  border-width: var(--cu-border-width-hairline);
}

:root .cu-button,
:root .cu-input,
:root .cu-textarea {
  border-radius: var(--cu-radius-md);
}

@media (prefers-reduced-transparency: reduce) {
  :root .cu-app-shell__header,
  :root .cu-navbar,
  :root .cu-tab-bar,
  :root .cu-navigation,
  :root .cu-sidebar,
  :root .cu-app-shell__sidebar,
  :root .cu-three-end-chrome,
  :root .cu-dialog__content,
  :root .cu-action-sheet__content,
  :root .cu-command-palette__content,
  :root .cu-sheet,
  :root .cu-drawer,
  :root .cu-popover__content,
  :root .cu-menu,
  :root .cu-hover-card,
  :root .cu-toast {
    -webkit-backdrop-filter: none;
    backdrop-filter: none;
    background: var(--cu-color-background-elevated);
  }
}

{
  "id": "apple",
  "label": "Apple",
  "preview": {
    "accent": "#007aff",
    "surface": "#f2f2f7"
  },
  "fonts": {
    "sans": "-apple-system, BlinkMacSystemFont, \"SF Pro Text\", \"SF Pro Display\", system-ui, sans-serif"
  }
}

{
  "radius": {
    "$type": "dimension",
    "sm": { "$value": { "value": 12, "unit": "px" } },
    "md": { "$value": { "value": 16, "unit": "px" } },
    "lg": { "$value": { "value": 20, "unit": "px" } },
    "xl": { "$value": { "value": 28, "unit": "px" } }
  },
  "blur": {
    "$type": "dimension",
    "surface": { "$value": { "value": 20, "unit": "px" } },
    "frost": { "$value": { "value": 20, "unit": "px" } },
    "thick": { "$value": { "value": 40, "unit": "px" } }
  },
  "saturate": {
    "$type": "number",
    "frost": { "$value": 1.8 }
  },
  "border": {
    "width": {
      "$type": "dimension",
      "hairline": { "$value": { "value": 1, "unit": "px" } },
      "default": { "$value": { "value": 1, "unit": "px" } }
    }
  },
  "shadow": {
    "sm": { "$value": "{shadow.md}" },
    "md": {
      "$value": "0 1px 2px color-mix(in srgb, #000 6%, transparent), 0 8px 24px color-mix(in srgb, #000 8%, transparent)"
    },
    "lg": {
      "$value": "0 10px 40px color-mix(in srgb, #000 12%, transparent)"
    },
    "soft": { "$value": "{shadow.md}" },
    "overlay": { "$value": "{shadow.lg}" },
    "none": { "$value": "none" }
  },
  "effect": {
    "frost": { "$value": "saturate(180%) blur(20px)" },
    "frost-thick": { "$value": "saturate(180%) blur(40px)" }
  },
  "font": {
    "family": {
      "sans": {
        "$value": "-apple-system, BlinkMacSystemFont, \"SF Pro Text\", \"SF Pro Display\", system-ui, sans-serif"
      }
    },
    "weight": {
      "semibold": { "$value": 600 }
    }
  },
  "color": {
    "palette": {
      "brand": { "$value": "#007aff" },
      "ink": { "$value": "#1c1c1e" },
      "paper": { "$value": "#ffffff" }
    },
    "background": {
      "default": { "$value": "#f2f2f7" },
      "subtle": { "$value": "#e5e5ea" },
      "elevated": { "$value": "#ffffff" },
      "inverse": { "$value": "#1c1c1e" },
      "translucent": { "$value": "color-mix(in srgb, #ffffff 72%, transparent)" },
      "translucent-thick": { "$value": "color-mix(in srgb, #ffffff 86%, transparent)" }
    },
    "border": {
      "default": { "$value": "color-mix(in srgb, #3c3c43 29%, transparent)" }
    },
    "fg": {
      "default": { "$value": "#1c1c1e" },
      "muted": { "$value": "#8e8e93" },
      "inverse": { "$value": "#f2f2f7" }
    }
  },
  "motion": {
    "duration": {
      "fast": { "$value": "120ms" },
      "base": { "$value": "200ms" },
      "slow": { "$value": "280ms" }
    },
    "easing": {
      "standard": { "$value": "cubic-bezier(0.25, 0.1, 0.25, 1)" },
      "enter": { "$value": "cubic-bezier(0, 0, 0.2, 1)" },
      "exit": { "$value": "cubic-bezier(0.4, 0, 1, 1)" }
    }
  },
  "typography": {
    "line-height": {
      "body": { "$value": 1.47 }
    }
  }
}
